BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE actor uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();member uuid;key uuid;domain uuid;visible uuid;hidden uuid;folder uuid;d jsonb;r jsonb;w jsonb;version uuid;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(outsider);INSERT INTO public.user_roles VALUES(actor,'admin');
 d:=public.redirect_domain_resource('create',actor,p_values=>'{"hostname":"qr-style.example.com"}');domain:=(d->>'id')::uuid;
 UPDATE public.redirect_domains SET ownership_state='verified',verified_until=now()+interval '1 day',provider_id='fixture-qr',routing_provider_id='fixture-qr',routing_protocol=1,routing_seen_at=now() WHERE id=domain;
 INSERT INTO public.redirect_domain_jobs(domain_id,zone_id,cname_target,requested_by,state,provider_status,ssl_status,checked_at) VALUES(domain,repeat('a',32),'links.queer.guide',actor,'ready','active','active',now());
 w:=public.redirect_qr_style_resource(actor);
 IF w->>'version' IS NOT NULL OR w->'style'<>'{}'::jsonb OR w#>>'{effectiveStyle,foreground}'<>'#111111' THEN RAISE EXCEPTION 'Missing preference did not use built-in defaults';END IF;
 w:=public.redirect_qr_style_resource(actor,p_values=>'{"version":null,"style":{"dots":"joined"}}');version:=(w->>'version')::uuid;
 BEGIN PERFORM public.redirect_qr_style_resource(actor,p_values=>'{"version":null,"style":{"dots":"circle"}}');RAISE EXCEPTION 'First-write conflict overwritten';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM public.redirect_qr_style_resource(outsider);RAISE EXCEPTION 'Non-owner read private settings';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 d:=public.redirect_qr_style_resource(actor,domain,'{"version":null,"style":{"border":"rounded","background":"#aaaaaa"}}');
 IF d#>>'{effectiveStyle,dots}'<>'joined' OR d#>>'{effectiveStyle,border}'<>'rounded' THEN RAISE EXCEPTION 'Domain did not inherit workspace appearance';END IF;
 BEGIN PERFORM public.redirect_qr_style_resource(actor,p_values=>jsonb_build_object('version',version,'style','{"foreground":"#555555"}'::jsonb));RAISE EXCEPTION 'Workspace edit invalidated a domain contrast';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF public.redirect_qr_style_resource(actor)->>'version'<>version::text THEN RAISE EXCEPTION 'Failed contrast update changed version';END IF;
 BEGIN PERFORM public.redirect_qr_style_resource(actor,p_values=>jsonb_build_object('version',version,'style','{"unknown":null}'::jsonb));RAISE EXCEPTION 'Unknown null field accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.redirect_qr_style_resource(actor,p_values=>jsonb_build_object('version',version,'style','{"dots":"triangle"}'::jsonb));RAISE EXCEPTION 'Unknown shape accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 d:=public.redirect_qr_style_resource(actor,domain,jsonb_build_object('version',d->>'version','style','{"background":null}'::jsonb));
 w:=public.redirect_qr_style_resource(actor,p_values=>jsonb_build_object('version',version,'style','{"foreground":"#555555"}'::jsonb));
 IF public.redirect_qr_style_resource(actor,domain)#>>'{effectiveStyle,foreground}'<>'#555555' THEN RAISE EXCEPTION 'Inherited field failed to follow workspace update';END IF;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Hidden QR','none') RETURNING id INTO folder;
 r:=public.redirect_management_mutate(jsonb_build_array(jsonb_build_object('operation','create','data',jsonb_build_object('target','/events','domainId',domain,'isDomainRoot',true))));visible:=(r#>>'{0,link,id}')::uuid;
 r:=public.redirect_management_mutate(jsonb_build_array(jsonb_build_object('operation','create','data',jsonb_build_object('target','/events','folderId',folder))));hidden:=(r#>>'{0,link,id}')::uuid;
 INSERT INTO public.redirect_workspace_members(user_id,kind,role,label) VALUES(outsider,'user','viewer','QR viewer') RETURNING id INTO member;
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,redirect_ids,member_id,created_by,expires_at) VALUES('QR key',repeat('e',64),'fixture',ARRAY['links:read'],ARRAY[visible],member,actor,now()+interval '1 day') RETURNING id INTO key;
 r:=public.redirect_qr_styles_for_links(ARRAY[visible],key);
 IF r#>>'{0,source}'<>'domain' OR r#>>'{0,style,dots}'<>'joined' OR (r->0)-ARRAY['id','style','source']::text[]<>'{}' THEN RAISE EXCEPTION 'Effective style inheritance or minimal fields incorrect';END IF;
 BEGIN PERFORM public.redirect_qr_styles_for_links(ARRAY[visible,hidden],key);RAISE EXCEPTION 'Scoped read exposed hidden link';EXCEPTION WHEN no_data_found THEN NULL;END;
 d:=public.redirect_qr_style_resource(actor,domain,jsonb_build_object('version',d->>'version','style',NULL));
 IF d->'style'<>'{}'::jsonb OR public.redirect_qr_styles_for_links(ARRAY[visible],key)#>>'{0,source}'<>'workspace' THEN RAISE EXCEPTION 'Reset did not restore inheritance';END IF;
 UPDATE public.redirect_domains SET disabled=true WHERE id=domain;
 IF public.redirect_qr_styles_for_links(ARRAY[visible],key)#>>'{0,style,dots}'<>'joined' THEN RAISE EXCEPTION 'QR branding incorrectly depends on routing readiness';END IF;
 UPDATE public.redirect_api_tokens SET revoked_at=now() WHERE id=key;
 BEGIN PERFORM public.redirect_qr_styles_for_links(ARRAY[visible],key);RAISE EXCEPTION 'Revoked key read style';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_table_privilege('authenticated','public.redirect_qr_styles','SELECT') OR has_function_privilege('anon','public.redirect_qr_styles_for_links(uuid[],uuid)','execute') THEN RAISE EXCEPTION 'Private QR defaults exposed';END IF;
END $$;
ROLLBACK;
